package com.autoops.command.retrieval;import com.autoops.command.entity.CommandDefinition;import com.autoops.command.repository.CommandDefinitionRepository;import org.springframework.stereotype.Service;import java.util.*;@Service public class CommandRetrievalService{private final CommandDefinitionRepository repo;public CommandRetrievalService(CommandDefinitionRepository r){repo=r;}public Result search(String query){String q=query.toLowerCase(Locale.ROOT);var scored=repo.findByStatusOrderByNameAsc("APPROVED").stream().map(c->new Scored(c,score(c,q))).filter(x->x.score>0).sorted(Comparator.comparingDouble(Scored::score).reversed()).limit(5).toList();if(scored.isEmpty())return new Result("NO_CONFIDENT_MATCH",List.of());if(scored.size()>1&&scored.get(0).score-scored.get(1).score<.15)return new Result("AMBIGUOUS",scored);return new Result(scored.get(0).score>=.45?"MATCH":"NO_CONFIDENT_MATCH",scored);}private double score(CommandDefinition c,String q){String text=(c.getName()+" "+c.getDescription()+" "+c.getCategory()).toLowerCase(Locale.ROOT);long hits=Arrays.stream(q.split("\\s+")).filter(w->w.length()>2&&text.contains(w)).count();return Math.min(1.0,hits/(double)Math.max(1,q.split("\\s+").length));}public record Scored(CommandDefinition command,double score){}public record Result(String confidence,List<Scored>matches){}}
